import classNames from 'classnames'
import type * as React from 'react'

import styles from './Badge.module.css'

type Props = {
  dataTestId?: string
  className?: string
  labelClassName?: string
  label?: React.ReactNode
  clickable?: boolean
  children?: React.ReactNode
  onClick?: () => void
}
function Badge({
  className,
  label,
  labelClassName,
  dataTestId,
  clickable,
  onClick,
  children,
}: Props) {
  return (
    <div
      role={'presentation'}
      data-test={dataTestId}
      className={classNames(styles.container, className, {[styles.clickable]: clickable})}
      onClick={onClick}
    >
      {label && <div className={classNames(styles.label, labelClassName)}>{label}</div>}
      {children}
    </div>
  )
}

export default Badge
